import{_ as p}from"./plugin-vue_export-helper-c27b6911.js";import{r as i,o as r,c,a as s,b as n,e as t,f as e}from"./app-32539e2b.js";const d="/assets/image-20230201122342515-d7d32d07.png",l="/assets/image-20230201124415408-d95b52ae.png",g="/assets/image-20230201132446996-f588324e.png",u="/assets/image-20230201132525052-6990f20a.png",k="/assets/image-20230201132647541-aaacfca1.png",o="/assets/image-20230202094609896-4c79a33c.png",m="/assets/image-20230202094634274-912d3984.png",h="/assets/image-20230202094708070-09e09fef.png",f="/assets/image-20230202094729775-91a84e43.png",b="/assets/image-20230202094759866-4a3b07e9.png",_="/assets/image-20230202094824490-0030715e.png",y={},v=s("h1",{id:"数据库主键一定要自增吗-有哪些场景不建议自增",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#数据库主键一定要自增吗-有哪些场景不建议自增","aria-hidden":"true"},"#"),n(" 数据库主键一定要自增吗？有哪些场景不建议自增？")],-1),w={href:"https://link.zhihu.com/?target=https%3A//mp.weixin.qq.com/s/vNRIFKjbe7itRTxmq-bkAA",target:"_blank",rel:"noopener noreferrer"},x=e('<p>我们平时建表的时候，一般会像下面这样。</p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">CREATE</span> <span class="token keyword">TABLE</span> <span class="token identifier"><span class="token punctuation">`</span>user<span class="token punctuation">`</span></span> <span class="token punctuation">(</span>\n  <span class="token identifier"><span class="token punctuation">`</span>id<span class="token punctuation">`</span></span> <span class="token keyword">int</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">AUTO_INCREMENT</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;主键&#39;</span><span class="token punctuation">,</span>\n  <span class="token identifier"><span class="token punctuation">`</span>name<span class="token punctuation">`</span></span> <span class="token keyword">char</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">DEFAULT</span> <span class="token string">&#39;&#39;</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;名字&#39;</span><span class="token punctuation">,</span>\n  <span class="token keyword">PRIMARY</span> <span class="token keyword">KEY</span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>id<span class="token punctuation">`</span></span><span class="token punctuation">)</span>\n<span class="token punctuation">)</span> <span class="token keyword">ENGINE</span><span class="token operator">=</span><span class="token keyword">InnoDB</span>  <span class="token keyword">DEFAULT</span> <span class="token keyword">CHARSET</span><span class="token operator">=</span>utf8mb4<span class="token punctuation">;</span>\n</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>出于习惯，我们一般会加一列 <strong>id 作为主键</strong>，而这个主键一般边上都有个 <code>AUTO_INCREMENT</code> , 意思是这个主键是自增的。自增就是i++，也就是每次都加1。</p><p>但问题来了。</p><p><strong>主键 id 不自增行不行？</strong></p><p><strong>为什么要用自增 id 做主键？</strong></p><p><strong>离谱点，没有主键可以吗？</strong></p><p><strong>什么情况下不应该自增？</strong></p><p>被这么一波追问，念头都不通达了？</p><p>这篇文章，我会尝试回答这几个问题。</p><h3 id="主键不自增行不行" tabindex="-1"><a class="header-anchor" href="#主键不自增行不行" aria-hidden="true">#</a> 主键不自增行不行</h3><p>当然是可以的。比如我们可以把建表 sql 里的 <code>AUTO_INCREMENT</code> 去掉。</p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">CREATE</span> <span class="token keyword">TABLE</span> <span class="token identifier"><span class="token punctuation">`</span>user<span class="token punctuation">`</span></span> <span class="token punctuation">(</span>\n  <span class="token identifier"><span class="token punctuation">`</span>id<span class="token punctuation">`</span></span> <span class="token keyword">int</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;主键&#39;</span><span class="token punctuation">,</span>\n  <span class="token identifier"><span class="token punctuation">`</span>name<span class="token punctuation">`</span></span> <span class="token keyword">char</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">DEFAULT</span> <span class="token string">&#39;&#39;</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;名字&#39;</span><span class="token punctuation">,</span>\n  <span class="token keyword">PRIMARY</span> <span class="token keyword">KEY</span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>id<span class="token punctuation">`</span></span><span class="token punctuation">)</span>\n<span class="token punctuation">)</span> <span class="token keyword">ENGINE</span><span class="token operator">=</span><span class="token keyword">InnoDB</span> <span class="token keyword">DEFAULT</span> <span class="token keyword">CHARSET</span><span class="token operator">=</span>utf8mb4<span class="token punctuation">;</span>\n</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后执行</p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">INSERT</span> <span class="token keyword">INTO</span> <span class="token identifier"><span class="token punctuation">`</span>user<span class="token punctuation">`</span></span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>name<span class="token punctuation">`</span></span><span class="token punctuation">)</span>  <span class="token keyword">VALUES</span>    <span class="token punctuation">(</span><span class="token string">&#39;debug&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这时候会报错 <code>Field &#39;id&#39; doesn&#39;t have a default value</code>。也就是说如果你不让主键自增的话，那你在写数据的时候需要自己指定id的值是多少，想要主键id是多少就写多少进去，不写就报错。</p><p>改成下面这样就好了</p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">INSERT</span> <span class="token keyword">INTO</span> <span class="token identifier"><span class="token punctuation">`</span>user<span class="token punctuation">`</span></span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>id<span class="token punctuation">`</span></span><span class="token punctuation">,</span><span class="token identifier"><span class="token punctuation">`</span>name<span class="token punctuation">`</span></span><span class="token punctuation">)</span>  <span class="token keyword">VALUES</span>    <span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token string">&#39;debug&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="为什么要用自增主键" tabindex="-1"><a class="header-anchor" href="#为什么要用自增主键" aria-hidden="true">#</a> 为什么要用自增主键</h3><p>我们在数据库里保存的数据就跟 excel 表一样，一行行似的。</p><figure><img src="'+d+'" alt="image-20230201122342515" tabindex="0" loading="lazy"><figcaption>image-20230201122342515</figcaption></figure><p>而在底层，这一行行数据，就是保存在一个个 <strong>16k 大小的页</strong>里。</p><p>每次都去遍历所有的行性能会不好，于是为了加速搜索，我们可以<strong>根据主键 id ，从小到大排列这些行数据</strong>，将这些数据页用<strong>双向链表</strong>的形式组织起来，再将这些页里的部分信息提取出来放到一个新的16kb的数据页里，再加入<strong>层级的概念</strong>。于是，一个个数据页就被组织起来了，成为了一棵 <strong>B+ 树索引</strong>。</p><figure><img src="'+l+'" alt="image-20230201124415408" tabindex="0" loading="lazy"><figcaption>image-20230201124415408</figcaption></figure><p>而当我们在建表 sql 里声明了<code>PRIMARY KEY (id)</code>时，mysql 的 innodb 引擎，就会为主键 id 生成一个<strong>主键索引</strong>，里面就是通过 B+ 树的形式来维护这套索引。</p><p>到这里，我们有<strong>两个点</strong>是需要关注的：</p><ul><li>数据页大小是<strong>固定16k</strong></li><li>数据页内，以及数据页之间，数据主键id都是从<strong>小到大排序</strong>的</li></ul><p>由于数据页大小<strong>固定了是16k</strong>，当我们需要插入一条新的数据，数据页会被慢慢<strong>放满</strong>，当超过16k时，这个数据页就有可能会进行<strong>分裂</strong>。</p><p>针对B+树<strong>叶子节点</strong>，<strong>如果主键是自增的</strong>，那它产生的id每次都比前一次要大，所以每次都会将数据加在B+树<strong>尾部</strong>，B+树的叶子节点本质上是<strong>双向链表</strong>，查找它的首部和尾部，<strong>时间复杂度 O(1)</strong>。而如果此时最末尾的数据页满了，那创建个新的页就好。</p><figure><img src="'+g+'" alt="image-20230201132446996" tabindex="0" loading="lazy"><figcaption>image-20230201132446996</figcaption></figure><p><strong>如果主键不是自增的</strong>，比方说上次分配了id=7，这次分配了id=3，为了让新加入数据后<strong>B+树的叶子节点还能保持有序</strong>，它就需要往叶子结点的中间找，查找过程的<strong>时间复杂度是O(lgn)</strong>，如果这个页正好也满了，这时候就需要进行<strong>页分裂</strong>了。并且页分裂操作本身是需要加<strong>悲观锁</strong>的。总体看下来，自增的主键遇到页分裂的可能性更少，因此性能也会更高。</p><figure><img src="'+u+'" alt="image-20230201132525052" tabindex="0" loading="lazy"><figcaption>image-20230201132525052</figcaption></figure><h3 id="没有主键可以吗" tabindex="-1"><a class="header-anchor" href="#没有主键可以吗" aria-hidden="true">#</a> 没有主键可以吗</h3><p>mysql表如果没有主键索引，查个数据都得全表扫描，那既然它这么重要，我今天就不当人了，<strong>不声明主键，可以吗？</strong></p><p>嗯，你完全可以不声明主键。</p><p>你确实可以在建表sql里写成这样。</p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">CREATE</span> <span class="token keyword">TABLE</span> <span class="token identifier"><span class="token punctuation">`</span>user<span class="token punctuation">`</span></span> <span class="token punctuation">(</span>\n  <span class="token identifier"><span class="token punctuation">`</span>name<span class="token punctuation">`</span></span> <span class="token keyword">char</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">DEFAULT</span> <span class="token string">&#39;&#39;</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;名字&#39;</span>\n<span class="token punctuation">)</span> <span class="token keyword">ENGINE</span><span class="token operator">=</span><span class="token keyword">InnoDB</span> <span class="token keyword">DEFAULT</span> <span class="token keyword">CHARSET</span><span class="token operator">=</span>utf8mb4<span class="token punctuation">;</span>\n</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看起来确实是没有主键的样子。然而实际上，mysql的innodb引擎内部会帮你生成一个名为<code>ROW_ID</code>列，它是个6字节的隐藏列，你平时也看不到它，但实际上，它也是自增的。有了这层兜底机制保证，<strong>数据表肯定会有主键和主键索引</strong>。</p>',38),E=s("code",null,"trx_id",-1),q=s("strong",null,"哪个事务",-1),T=s("code",null,"roll_pointer",-1),N=s("strong",null,"多版本并发控制（MVCC）",-1),A={href:"https://mp.weixin.qq.com/s?__biz=Mzg5NDY2MDk4Mw==&mid=2247488340&idx=1&sn=6c5a0743918d582eb6ee76571d992897&scene=21#wechat_redirect",target:"_blank",rel:"noopener noreferrer"},R=e('<figure><img src="'+k+'" alt="image-20230201132647541" tabindex="0" loading="lazy"><figcaption>image-20230201132647541</figcaption></figure><h3 id="有没有建议主键不自增的场景" tabindex="-1"><a class="header-anchor" href="#有没有建议主键不自增的场景" aria-hidden="true">#</a> 有没有建议主键不自增的场景</h3><p>前面提到了主键自增可以带来很多好处，事实上<strong>大部分场景下，我们都建议主键设为自增。</strong></p><p>那有没有不建议主键自增的场景呢？</p><h4 id="mysql分库分表下的id" tabindex="-1"><a class="header-anchor" href="#mysql分库分表下的id" aria-hidden="true">#</a> mysql分库分表下的id</h4><p>聊到分库分表，那我就需要说明下，<strong>递增和自增的区别</strong>了，<strong>自增</strong>就是每次都+1，而<strong>递增</strong>则是新的id比上一个id要大就行了，具体大多少，没关系。</p>',6),M={href:"https://mp.weixin.qq.com/s?__biz=Mzg5NDY2MDk4Mw==&mid=2247488672&idx=1&sn=b2e0ba15933587bab8d9ee636c59a963&scene=21#wechat_redirect",target:"_blank",rel:"noopener noreferrer"},I=e('<p>一种分表方式是通过<strong>对id取模进行分表</strong>，这种要求递增就好，不要求严格自增，因为取模后数据会被分散到多个分表中，就算id是严格自增的，在分散之后，都只能保证每个分表里id只能是递增的。</p><figure><img src="'+o+'" alt="image-20230202094609896" tabindex="0" loading="lazy"><figcaption>image-20230202094609896</figcaption></figure><figure><img src="'+o+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>另一种分表方式是<strong>根据id的范围进行分表（分片）</strong>，它会划出一定的范围，比如以2kw为一个分表的大小，那0<sub>2kw就放在这张分表中，2kw</sub>4kw放在另一张分表中，数据不断增加，分表也可以不断增加，<strong>非常适合动态扩容</strong>，但它要求<strong>id自增</strong>，如果<strong>id递增</strong>，数据则会出现<strong>大量空洞</strong>。举个例子，比如第一次分配id=2，第二次分配id=2kw，这时候第一张表的范围就被打满了，后面再分配一个id，比如是3kw，就只能存到2kw<sub>4kw（第二张）的分表中。那我在0</sub>2kw这个范围的分表，也就存了<strong>两条数据</strong>，这太浪费了。</p><figure><img src="'+m+'" alt="image-20230202094634274" tabindex="0" loading="lazy"><figcaption>image-20230202094634274</figcaption></figure><p>但不管哪种分表方式，一般是<strong>不可能继续用原来表里的自增主键的</strong>，原因也比较好理解，原来的每个表如果都从0开始自增的话，那好几个表就会出现好几次重复的id，根据id唯一的原则，这显然不合理。</p><p>所以我们在分库分表的场景下，插入的id都是专门的id服务生成的，如果是要严格自增的话，那一般会通过redis来获得，当然不会是一个id请求获取一次，一般会<strong>按批次去获得，比如一次性获得100个。快用完了再去获取下一批100个。</strong></p><p>但这个方案有个问题，它严重依赖redis，如果redis挂了，那整个功能就傻了。</p><p>有没有不依赖于其他第三方组件的方法呢？</p><h5 id="雪花算法" tabindex="-1"><a class="header-anchor" href="#雪花算法" aria-hidden="true">#</a> 雪花算法</h5><p>有，比如<strong>Twitter开源的雪花算法。</strong></p><p>雪花算法通过64位有特殊含义的数字来组成id。</p><figure><img src="'+h+'" alt="image-20230202094708070" tabindex="0" loading="lazy"><figcaption>image-20230202094708070</figcaption></figure><p>首先<strong>第0位</strong>不用。</p><p>接下来的<strong>41位</strong>是<strong>时间戳</strong>。精度是<strong>毫秒</strong>，这个大小大概能表示个<code>69年</code>左右，因为时间戳随着时间流逝肯定是越来越大的，所以这部分决定了生成的id肯定是越来越大的。</p><p>再接下来的<strong>10位</strong>是指产生这些雪花算法的<strong>工作机器id</strong>，这样就可以让每个机器产生的id都具有相应的标识。</p><p>再接下来的<strong>12位</strong>，<strong>序列号</strong>，就是指这个工作机器里生成的递增数字。</p><p>可以看出，只要处于同一毫秒内，所有的雪花算法id的前42位的值都是一样的，因此在这一毫秒内，能产生的id数量就是 <code>2的10次方✖️2的12次方</code>，大概<code>400w</code>，肯定是够用了，甚至有点多了。</p><p><strong>但是！</strong></p><p>细心的兄弟们肯定也发现了，雪花算法它算出的数字动不动就比上次的数字多个几百几万的，也就是它生成的id是<strong>趋势递增</strong>的，并不是严格**+1自增**的，也就是说它并不太适合于根据范围来分表的场景。这是个非常疼的问题。</p><p>还有个<strong>小问题</strong>是，那10位工作机器id，我每次扩容一个工作机器，这个机器怎么知道自己的id是多少呢？是不是得从某个地方读过来。</p><p><strong>那有没有一种生成id生成方案，既能让分库分表能做到很好的支持动态扩容，又能像雪花算法那样并不依赖redis这样的第三方服务。</strong></p><p>有。这就是这篇文章的重点了。</p><h5 id="适合分库分表的uuid算法" tabindex="-1"><a class="header-anchor" href="#适合分库分表的uuid算法" aria-hidden="true">#</a> 适合分库分表的uuid算法</h5><p>我们可以参考雪花算法的实现，可设计成下面这样。注意下面的每一位，<strong>都是十进制</strong>，而不是二进制。</p><figure><img src="'+f+'" alt="image-20230202094729775" tabindex="0" loading="lazy"><figcaption>image-20230202094729775</figcaption></figure><p>开头的<strong>12位</strong>依然是时间，但并不是时间戳，雪花算法的时间戳精确到毫秒，我们用不上这么细，我们改为<code>yyMMddHHmmss</code>，注意开头的yy是两位，也就是这个方案能保证到2099年之前，id都不会重复，能用到重复，那也是真·百年企业。同样由于最前面是时间，随着时间流逝，也能保证id趋势递增。</p><p>接下来的<strong>10位</strong>，用<strong>十进制</strong>的方式表示工作机器的ip，就可以把12位的ip转为10位的数字，它可以保证全局唯一，只要服务起来了，也就知道自己的ip是多少了，不需要像雪花算法那样从别的地方去读取worker id了，又是一个小细节。</p><p>在接下来的<strong>6位</strong>，就用于生成序列号，它能支持每秒钟生成100w个id。</p><p>最后的<strong>4位</strong>，也是这个id算法最妙的部分。它<strong>前2位</strong>代表分库id，<strong>后2位</strong>代表分表id。也就是支持一共<code>100*100=1w</code>张分表。</p><p>举个例子，假设我只用了1个分库，当我一开始只有3张分表的情况下，那我可以通过配置，要求生成的uuid最后面的2位，取值只能是[0,1,2]，分别对应三个表。这样我生成出来的id，就能非常均匀的落到三个分表中，这还<strong>顺带解决了单个分表热点写入的问题。</strong></p><p>如果随着业务不断发展，需要新加入两张新的表(3和4)，同时第0张表有点满了，不希望再被写了，那就将配置改为[1,2,3,4]，这样生成的id就不会再插入到对应的0表中。同时还可以加入生成id的<strong>概率和权重</strong>来调整哪个分表落更多数据。</p><p>有了这个新的uuid方案，我们<strong>既可以保证生成的数据趋势递增，同时也能非常方便扩展分表</strong>。非常nice。</p><p>数据库有那么多种，mysql只是其中一种，那其他数据库也是要求主键自增吗？</p><blockquote><ul><li>秋迟注：</li></ul><p>以上应该是原作者推荐的一种 UUID 编码方式，没用 16 进制，只能说是按照作者喜好吧。读者也可以根据自己实际进行编码。</p><p>更多编码方式可以参照我的另一篇<a href="">文章</a>。</p></blockquote><h4 id="tidb的主键id不建议自增" tabindex="-1"><a class="header-anchor" href="#tidb的主键id不建议自增" aria-hidden="true">#</a> tidb的主键id不建议自增</h4><p>tidb是一款分布式数据库，作为mysql分库分表场景下的替代产品，可以更好的对数据进行分片。</p><p>它通过引入<strong>Range</strong>的概念进行数据表分片，比如第一个分片表的id在0<sub>2kw，第二个分片表的id在2kw</sub>4kw。这其实就是<strong>根据id范围进行数据库分表</strong>。</p><p>它的语法几乎跟mysql一致，用起来大部分时候是无感的。</p><p>但跟mysql有一点很不一样的就是，mysql建议id自增，但<strong>tidb却建议使用随机的uuid</strong>。原因是如果id自增的话，根据范围分片的规则，一段时间内生成的id几乎都会落到同一个分片上，比如下图，从<code>3kw</code>开始的自增uuid，几乎都落到<code>range 1</code>这个分片中，而其他表却几乎不会有写入，性能没有被利用起来。出现<strong>一表有难，多表围观</strong>的场面，这种情况又叫<strong>写热点</strong>问题。</p><figure><img src="'+b+'" alt="image-20230202094759866" tabindex="0" loading="lazy"><figcaption>image-20230202094759866</figcaption></figure><p>所以为了充分的利用多个分表的写入能力，tidb建议我们写入时使用<strong>随机id</strong>，这样数据就能被均匀分散到多个分片中。</p><h4 id="用户id不建议用自增id" tabindex="-1"><a class="header-anchor" href="#用户id不建议用自增id" aria-hidden="true">#</a> 用户id不建议用自增id</h4><p>前面提到的不建议使用自增id的场景，都是技术原因导致的，而下面介绍的这个，单纯是因为业务。</p><p>举个例子吧。</p><p>xxxxxxxxxx import { defaultTheme } from &#39;vuepress&#39;;import vuepressPluginAnchorRight from &#39;vuepress-plugin-anchor-right&#39;;​​export default {​  plugins: [   [vuepressPluginAnchorRight()], ],  lang: &#39;zh-CN&#39;,  title: &#39;秋迟先生&#39;,  description: &#39;有趣的知识库&#39;,  head: [[    // 设置 favor.ico，.vuepress/public 下        &#39;link&#39;, { rel: &#39;icon&#39;, href: &#39;/images/avatar.jpg&#39; }] ],  theme: defaultTheme({    // 默认主题配置    logo: &#39;/images/avatar.jpg&#39;,    ... }),}javascript</p><p>对程序员来说，可能这个信息价值不大。</p><p>但如果你是做投资的呢，或者是分析竞争对手呢？</p><p>那反过来。</p><p>如果你发现你的竞争对手，总能非常清晰的知道你的产品每个月新进的注册用户是多少人，你会不会心里毛毛的？</p><p>如果真出现了这问题，先不要想是不是有内鬼，先检查下你的用户表主键是不是自增的。</p><figure><img src="'+_+'" alt="image-20230202094824490" tabindex="0" loading="lazy"><figcaption>image-20230202094824490</figcaption></figure><p><strong>如果用户id是自增的，那别人只要每个月都注册一个新用户，然后抓包得到这个用户的user_id，然后跟上个月的值减一下，就知道这个月新进多少用户了。</strong></p><p>同样的场景有很多，有时候你去小店吃饭，发票上就写了你是今天的第几单，那大概就能估计今天店家做了多少单。你是店家，你心里也不舒服吧。</p><p>再比如说一些小app的商品订单id，如果也做成自增的，那就很容易可以知道这个月成了多少单。</p><p>类似的事情有很多，这些场景都建议使用趋势递增的uuid作为主键。</p><p>当然，<strong>主键保持自增，但是不暴露给前端，那也行，那前面的话，你当我没说过</strong>。</p><h3 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> 总结</h3><ul><li>建表sql里主键边上的<code>AUTO_INCREMENT</code>，可以让主键自增，去掉它是可以的，但这就需要你在insert的时候自己设置主键的值。</li><li>建表sql里的 <code>PRIMARY KEY</code> 是用来声明主键的，如果去掉，那也能建表成功，但mysql内部会给你偷偷建一个 <code>ROW_ID</code>的隐藏列作为主键。</li><li>由于mysql使用<strong>B+树索引，叶子节点是从小到大排序的</strong>，如果使用自增id做主键，这样每次数据都加在B+树的最后，比起每次加在B+树中间的方式，加在最后可以有效<strong>减少页分裂的问题。</strong></li><li>在分库分表的场景下，我们可以通过redis等第三方组件来获得严格自增的主键id。如果不想依赖redis，可以参考雪花算法进行<strong>魔改</strong>，<strong>既能保证数据趋势递增，也能很好的满足分库分表的动态扩容。</strong></li><li>并不是所有数据库都建议使用自增id作为主键，比如<strong>tidb就推荐使用随机id</strong>，这样可以有效避免<strong>写热点</strong>的问题。而对于一些敏感数据，比如用户id，订单id等，如果使用自增id作为主键的话，外部通过抓包，很容易可以知道新进用户量，成单量这些信息，所以需要<strong>谨慎考虑</strong>是否继续使用自增主键。</li></ul>',59);function L(O,C){const a=i("ExternalLinkIcon");return r(),c("div",null,[v,s("blockquote",null,[s("p",null,[n("本文节选自个人公众号《小白debug》文章：《"),s("a",w,[n("数据库主键一定要自增的吗？有哪些场景下不建议自增"),t(a)]),n("》@qiuchi")])]),x,s("p",null,[n("跟ROW_ID被隐藏的列还有"),E,n("字段，用于记录当前这一行数据行是被"),q,n("修改的，和一个"),T,n("字段，这个字段是用来指向当前这个数据行的上一个版本，通过这个字段，可以为这行数据形成一条版本链，从而实现"),N,n("。有没有很眼熟，这个在之前写的"),s("a",A,[n("文章"),t(a)]),n("里出现过。")]),R,s("p",null,[n("之前写过一篇"),s("a",M,[n("文章"),t(a)]),n("提到过，mysql在水平分库分表时，一般有两种方式。")]),I])}const B=p(y,[["render",L],["__file","01does_the_database_primary_key_have_to_be_auto-incremented.html.vue"]]);export{B as default};
